  const p = await figma.getNodeByIdAsync(id);
  await figma.setCurrentPageAsync(p);
  out.push('=== '+p.name);
  const walk=(n,d)=>{
    let s='  '.repeat(d)+n.type+' '+n.id+' "'+n.name+'"';
    if('width' in n) s+=` ${Math.round(n.x)},${Math.round(n.y)} ${Math.round(n.width)}x${Math.round(n.height)}`;
    if(n.type==='TEXT') s+=' :: '+n.characters;
    if('fills' in n && n.type!=='TEXT' && Array.isArray(n.fills) && n.fills[0]?.type==='SOLID'){const c=n.fills[0].color;s+=' fill#'+[c.r,c.g,c.b].map(v=>Math.round(v*255).toString(16).padStart(2,'0')).join('');}
    out.push(s);
    if('children' in n) n.children.forEach(c=>walk(c,d+1));
  };
  p.children.forEach(c=>walk(c,0));
}
return out.join('\n');

