function AL(name,dir='HORIZONTAL',o={}){const f=figma.createFrame(); f.name=name; f.layoutMode=dir; f.fills=o.fill?[P(o.fill)]:[]; f.itemSpacing=o.gap||0; const p=o.pad||[0,0,0,0]; [f.paddingTop,f.paddingRight,f.paddingBottom,f.paddingLeft]=p; f.primaryAxisAlignItems=o.pa||'MIN'; f.counterAxisAlignItems=o.ca||'CENTER'; if(o.r!==undefined) f.cornerRadius=o.r; f.clipsContent=false; if(o.w){f.resize(o.w,o.h||10);} f.primaryAxisSizingMode=o.ps||'AUTO'; f.counterAxisSizingMode=o.cs||'AUTO'; return f;}
